export class AudioEngine{
 constructor(){this.context=null;this.buffers={};this.muted=false;this.ready=false;this.last={};this.volume=.62;}
 async unlock(){if(this.context?.state==='suspended')await this.context.resume();if(this.ready)return;if(this.pending)return this.pending;this.pending=this.init();return this.pending;}
 async init(){try{this.context=new (window.AudioContext||window.webkitAudioContext)();await this.context.resume();this.master=this.context.createGain();this.master.gain.value=this.volume;this.master.connect(this.context.destination);const names=['sword','impact','ember','dodge','hurt','death','heal','pickup','step','bell','roar','ambience'];await Promise.all(names.map(async name=>{try{const res=await fetch(`/assets/audio/${name}.wav`);this.buffers[name]=await this.context.decodeAudioData(await res.arrayBuffer());}catch(e){console.warn('Sound unavailable:',name);}}));this.ready=true;this.ambience=this.play('ambience',.45,1,true);this.play('bell',.3);}catch(e){console.warn('Audio unavailable',e);}}
 play(name,volume=1,rate=1,loop=false){if(!this.ready||!this.buffers[name]||this.muted)return null;const now=this.context.currentTime;if(!loop&&now-(this.last[name]??-1)<.055)return null;this.last[name]=now;const source=this.context.createBufferSource();source.buffer=this.buffers[name];source.playbackRate.value=rate;source.loop=loop;const gain=this.context.createGain();gain.gain.value=volume;source.connect(gain);gain.connect(this.master);source.start();source.onended=()=>{source.disconnect();gain.disconnect();};return source;}
 toggle(){this.muted=!this.muted;if(this.master)this.master.gain.setTargetAtTime(this.muted?0:this.volume,this.context.currentTime,.08);if(!this.muted&&this.ready&&!this.ambience)this.ambience=this.play('ambience',.45,1,true);return this.muted;}
 pause(value){if(this.master)this.master.gain.setTargetAtTime(this.muted?0:value?this.volume*.2:this.volume,this.context.currentTime,.12);}
}
